STORY = [('seungchan', '자기는 그런 사람 아니라고 하시더라고요.', 'She said she is not that kind of person.', [(268, '자기는 그런 사람 아니라고 하시더라고요')], ''), ('baek_mom', '예의가 바르네.', 'She is very polite.', [(269, '겸허가 바르네')], 'Adjusts STT typo 겸허가 to 예의가 바르네.'), ('baek_dad', '당연한 거지.', 'That is natural.', [(270, '당연한 거지')], ''), ('baek_dad', '아, 그리고 아버지 고등학교 동창이 너한테 제보할 게 있다더니.', "Oh, and your father's high school classmate said he has a tip-off for you.", [(271, '아, 그리고 아버지 고등학교 동창이 너한테 제보할 게 있다더니.')], ''), ('seungchan', '무슨 얘기입니까?', 'What is the story?', [(272, '무슨 얘기입니까?')], ''), ('baek_dad', '주인이 프랜차이즈 뭐 큰 게 들어온다고,', 'The landlord said a big franchise is moving in,', [(274, '주인이 프랜차이즈 뭐 큰 게 들어온다고')], ''), ('baek_dad', '권리금도 받지 말고 나가라고 한대요.', 'and told him to leave without even getting his premium back.', [(275, '권리금도 받지 말고 나가라고 한대요.')], ''), ('seungchan', '그 얘기를 왜 저한테?', 'Why is he telling me that story?', [(276, '그 얘기를 왜 저한테?')], ''), ('baek_dad', '우리 아들이 KBS 피디라고 하니까', 'Because he heard my son is a KBS producer,', [(278, '우리 아들이 KBS 피디라고 하니까 이런 걸')], ''), ('baek_dad', '피디수첩 같은 데서 좀 다뤄 달라고.', 'he asked you to cover it on a show like PD Note.', [(279, '피디수첩 같은 데서 좀 다뤄달라고.')], ''), ('seungchan', '저는 예능국인데요, 아버지.', 'I am in the variety department, Father.', [(283, '저는 예능국인데요, 아버지.')], '')]

